using System;using System.IO;
// Current Script.pvf: Linus.npc role shop2 -> EquipmentShop1.shp,
// stackable/ptn_hplowest.stk item1106 price100, stack1000, HP70, cooldown10s.
// FG67 also admits shop2 MP potion1112: price100, MP65, cooldown10s/group1.
class Offline70NpcPurchaseFG44 {
 internal static void Register(){Offline70Economy.RegisterMetadata(new Offline70EconomyItemDefinition{ItemId=1112,Kind=1,StackLimit=1000,MpRecovery=65,CooldownMilliseconds=10000,CooldownGroup=1});Offline70Economy.RegisterMetadata(new Offline70EconomyItemDefinition{ItemId=1106,Kind=1,StackLimit=1000,HpRecovery=70,CooldownMilliseconds=10000,CooldownGroup=0});}
 internal static uint Parse(byte[] cipher,byte[] keys){uint id;uint count=Parse(cipher,keys,out id);if(id!=1106)throw new InvalidDataException("Legacy HP offer");return count;}
 internal static uint Parse(byte[] cipher,byte[] keys,out uint id){uint shop;uint count=Parse(cipher,keys,out id,out shop);if(shop!=2)throw new InvalidDataException("Legacy Linus offer");return count;}
 internal static uint Parse(byte[] cipher,byte[] keys,out uint id,out uint shop){if(cipher==null||cipher.Length!=16)throw new InvalidDataException("NPC21 request length");byte[] b=Offline70RoleProtocol.BatchCryptFG(cipher,keys,7,false);id=BitConverter.ToUInt32(b,0);shop=BitConverter.ToUInt32(b,8);if(BitConverter.ToUInt32(b,12)!=0)throw new InvalidDataException("NPC purchase reserved field");uint count=BitConverter.ToUInt32(b,4);Offline70CommerceFG71.BuyCost(shop,id,count);return count;}
 internal static Offline70EconomyState Purchase(string path,string receipt,uint count,out bool duplicate){return Purchase(path,receipt,1106,count,out duplicate);}
 internal static Offline70EconomyState Purchase(string path,string receipt,uint id,uint count,out bool duplicate){return Purchase(path,receipt,2,id,count,out duplicate);}
 internal static Offline70EconomyState Purchase(string path,string receipt,uint shop,uint id,uint count,out bool duplicate){uint cost=Offline70CommerceFG71.BuyCost(shop,id,count);uint price=Offline70CommerceFG71.OfferPrice(shop,id);return Offline70Economy.Apply(path,receipt,"npc-purchase","shop"+shop+":"+id+":"+count+":"+price,delegate(Offline70EconomyState s){if(s.Gold<cost)throw new InvalidDataException("Insufficient gold");Offline70Economy.AddPurchasedItem(s,id,count);s.Gold-=cost;},out duplicate);}
 // Native C11CD0 calls the existing stack's ADD-quantity method. A new item
 // receives its full quantity; an existing stack receives only this purchase's gain.
 internal static byte[] PurchaseReply(Offline70EconomyState before,Offline70EconomyState after,Offline70EconomyEntry row,byte[] keys){Offline70EconomyEntry old=Offline70Economy.Find(before,row.List,row.Slot);uint prior=old!=null&&old.ItemId==row.ItemId?old.Quantity:0;if(row.Quantity<=prior)throw new InvalidDataException("Purchase delta missing");Offline70EconomyEntry wire=new Offline70EconomyEntry{List=row.List,Slot=row.Slot,ItemId=row.ItemId,Quantity=row.Quantity-prior,Durability=row.Durability};return Reply(after,wire,true,keys);}
 internal static byte[] Reply(Offline70EconomyState s,Offline70EconomyEntry row,bool success,byte[] keys){using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write((byte)(success?1:0));if(!success)w.Write((byte)0x13);else{if(row==null||row.List!=0||Offline70Economy.Definition(row.ItemId).Kind!=1&&Offline70Economy.Definition(row.ItemId).Kind!=2&&Offline70Economy.Definition(row.ItemId).Kind!=4)throw new InvalidDataException("NPC reply item");w.Write(s.Gold);w.Write((uint)0);w.Write((uint)0);w.Write(s.OfflineCash);w.Write(row.Slot);w.Write(row.ItemId);w.Write(row.Quantity);w.Write(row.Durability);w.Write((byte)0);w.Write((ushort)0);w.Write((uint)0);w.Write((byte)0);/*463C20 option-vector count*/w.Write((ushort)0);/*40B1F0 state*/w.Write((byte)0);/*C7E980 list count, zero skips entries and their suffix*/w.Write((byte)0);w.Write(UInt32.MaxValue);w.Write((uint)0);}return Offline70RoleProtocol.BatchPacketFG(1,21,m.ToArray(),keys,true);}}
 // Native21 updates the primary stack and wallet. Only additional changed stacks
 // need notify14; never reload the whole inventory during a shop transaction.
 internal static byte[] AdditionalRows(Offline70EconomyState before,Offline70EconomyState after,Offline70EconomyEntry primary,byte[] keys){using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write((byte)0);w.Write((ushort)0);ushort count=0;foreach(Offline70EconomyEntry e in after.Inventory){if(e.List!=0||e.Slot==primary.Slot)continue;Offline70EconomyEntry old=Offline70Economy.Find(before,e.List,e.Slot);if(old==null||old.ItemId!=e.ItemId||old.Quantity!=e.Quantity){w.Write(Offline70EconomyProtocol.InventoryRow(e));count++;}}if(count==0)return null;byte[] body=m.ToArray();BitConverter.GetBytes(count).CopyTo(body,1);return Offline70EconomyProtocol.UpdatePacket(body,keys);}}

}

